967-      # against the committed v1.0.493 release baseline. Shrink passes;
968-      # growth (e.g. a dropped interpreter re-added) fails the release.
969-      - name: Size manifest + budget gate (fa-extension.zip)
970:        run: python3 scripts/size_manifest.py check build/fa-extension.zip --baseline scripts/size_budget/fa-extension.tsv
971-
972-      - name: Upload extension to the release
973-        env:
974-          GH_TOKEN: ${{ secrets.RELEASE_PAT }}
975-          RELEASE_TAG: ${{ needs.version.outputs.tag }}
976-        run: |

