{"command":"cd /home/runner/work/flutter_agent_harness/flutter_agent_harness && git show origin/main:scripts/size_budget/fa-extension.tsv > /tmp/old.tsv && python3 - <<'EOF'
old = {}
for line in open('/tmp/old.tsv'):
    line = line.rstrip('\n')
    if not line.strip(): continue
    s, _, n = line.partition('\t')
    old[n] = int(s)
new = {}
for line in open('scripts/size_budget/fa-extension.tsv'):
    line = line.rstrip('\n')
    if not line.strip(): continue
    s, _, n = line.partition('\t')
    new[n] = int(s)

# map old rev lines -> new rev lines by suffix
rev_old = '692136cb6582dbfc5af3fb33c2515a069f2f66d0'
rev_new = 'deb287481e3ce9468f3434937ced4240a70539ca'
mismatches = []
for n, v in old.items():
    if rev_old in n:
        nn = n.replace(rev_old, rev_new)
        if nn not in new:
            mismatches.append(('missing', nn))
        elif new[nn] != v:
            mismatches.append(('size', nn, v, new[nn]))
for n, v in new.items():
    if rev_new in n:
        on = n.replace(rev_new, rev_old)
        if on not in old:
            mismatches.append(('extra', n))
print('line-count old/new:', len(old), len(new))
print('TOTAL old/new:', old.get('TOTAL'), new.get('TOTAL'))
print('mismatches:', mismatches if mismatches else 'NONE — pure path substitution confirmed')
# sortedness per write_baseline: sorted(manifest) over all keys incl TOTAL
names = list(new.keys())
print('file sorted:', names == sorted(names))
# TOTAL == sum of non-TOTAL rows
print('TOTAL sum consistent:', sum(v for k, v in new.items() if k != 'TOTAL') == new['TOTAL'])
EOF"}

